mapper.select:
select a.id
from b_xiecheng_colliding_data_rob a
join (${queryRuleScoreDataSql}) AS b on a.cell_sha256_code_list = b.cell and b.is_delete = 0
where a.is_delete = 0 and a.package_id = #{packageId}

    and a.id > #{minId}

order by a.id
limit 2000;

SELECT a.id, a.cell FROM (${queryRuleScoreDataSql}) AS a LEFT JOIN b_xiecheng_colliding_data_loop_cycle AS b ON a.cell = b.cell_sha256_code_list AND b.is_delete = 0 LEFT JOIN b_xiecheng_colliding_data_rob AS c ON a.cell = c.cell_sha256_code_list and c.is_delete = 0 WHERE b.id IS NULL AND c.id IS NULL AND a.is_delete = 0
and a.id > #{minId}
order by a.id LIMIT #{pageSize};

mapper.update:
update ${tableName} set is_delete = 1,update_time = now(),extend = #{extend}
where id in
      (SELECT id
       FROM (SELECT id,cell,ROW_NUMBER() OVER (PARTITION BY cell ORDER BY id) AS row_num
             FROM ${tableName} where is_delete = 0) AS a
       WHERE row_num > 1 limit 2000);
